INSERT INTO "Fruit" ("id", "slug", "name", "variety", "illustration", "color", "imageUrl", "origin", "region", "farmer", "season", "description", "taste", "storage", "ripeness", "goodToKnow", "reviewed", "active", "createdAt", "updatedAt") VALUES ('cmwjc5xob000n7dltycricss6', 'mango-kent', 'Mango Kent', 'Kent', 'mango', '#F6A623', '', 'Spánn', '', '', 'Sumar og haust', 'Kent er eitt vinsælasta mangóafbrigðið. Aldinkjötið er safaríkt og nánast trefjalaust, svo það er auðvelt að skera og borða.', 'Sætt og djúpt bragð.', 'Geymdu við stofuhita þar til það er þroskað, svo í kæli í 2–3 daga.', 'Þroskað mangó gefur aðeins eftir þegar þrýst er létt á það og ilmar sætt við stilkinn. Áferðin segir meira um þroska en liturinn.', 'Hýðið fær oft rauðan roða þar sem sólin skín á ávöxtinn.', false, true, '2026-11-16 14:05:34.524', '2026-11-16 14:05:34.524') ON CONFLICT DO NOTHING;
INSERT INTO "Fruit" ("id", "slug", "name", "variety", "illustration", "color", "imageUrl", "origin", "region", "farmer", "season", "description", "taste", "storage", "ripeness", "goodToKnow", "reviewed", "active", "createdAt", "updatedAt") VALUES ('cmwjc5xqu000o7dltoth0swed', 'mandarina-oronules', 'Mandarina Oronules', 'Oronules', 'mandarin', '#F28A1E', '', 'Spánn', '', '', 'Haust', 'Oronules er snemmbúið klementínuafbrigði sem á rætur að rekja til Nules í Valencia-héraði á Spáni.', 'Safarík og sæt.', 'Geymist í kæli í 1–2 vikur, eða í skál á borðinu í nokkra daga.', 'Tilbúin til neyslu um leið og hún kemur.', 'Auðvelt að afhýða, fullkomin í nestisboxið.', false, true, '2026-11-16 14:05:34.615', '2026-11-16 14:05:34.615') ON CONFLICT DO NOTHING;
INSERT INTO "Fruit" ("id", "slug", "name", "variety", "illustration", "color", "imageUrl", "origin", "region", "farmer", "season", "description", "taste", "storage", "ripeness", "goodToKnow", "reviewed", "active", "createdAt", "updatedAt") VALUES ('cmwjc5xs3000p7dltke1ewtel', 'mango-keitt', 'Mango Keitt', 'Keitt', 'mango-green', '#8CBF3F', '', 'Spánn', '', '', 'Haust', 'Keitt er stórt mangóafbrigði sem er tínt seint á tímabilinu.', 'Sætt og ferskt, með þéttu aldinkjöti.', 'Við stofuhita þar til það er þroskað, svo í kæli.', 'Keitt helst grænt þótt það sé fullþroskað. Ekki láta litinn blekkja þig, finndu frekar hvort það gefur aðeins eftir.', 'Grænt hýði þýðir ekki að það sé óþroskað.', false, true, '2026-11-16 14:05:34.659', '2026-11-16 14:05:34.659') ON CONFLICT DO NOTHING;
INSERT INTO "Fruit" ("id", "slug", "name", "variety", "illustration", "color", "imageUrl", "origin", "region", "farmer", "season", "description", "taste", "storage", "ripeness", "goodToKnow", "reviewed", "active", "createdAt", "updatedAt") VALUES ('cmwjc5xtb000q7dlt69axtkss', 'granatepli', 'Granatepli', '', 'pomegranate', '#C8283A', '', 'Spánn', '', '', 'Haust', 'Inni í hörðu hýðinu eru hundruð safaríkra kjarna.', 'Sætt og örlítið súrt.', 'Geymist vel í kæli í nokkrar vikur.', 'Þungt granatepli miðað við stærð er yfirleitt safaríkt.', 'Skerðu granateplið í tvennt og bankaðu á hýðið með skeið yfir skál, þá detta kjarnarnir út.', false, true, '2026-11-16 14:05:34.703', '2026-11-16 14:05:34.703') ON CONFLICT DO NOTHING;
INSERT INTO "Fruit" ("id", "slug", "name", "variety", "illustration", "color", "imageUrl", "origin", "region", "farmer", "season", "description", "taste", "storage", "ripeness", "goodToKnow", "reviewed", "active", "createdAt", "updatedAt") VALUES ('cmwjc5xuj000r7dltyuogrx0b', 'avokado-bacon', 'Avókadó Bacon', 'Bacon', 'avocado', '#2F5A22', '', 'Spánn', '', '', 'Vetur', 'Bacon er vetrarafbrigði með þunnu, sléttu, grænu hýði sem helst grænt þegar avókadóið þroskast.', 'Létt og milt.', 'Við stofuhita þar til það er þroskað, svo í kæli í 2–3 daga.', 'Tilbúið þegar það gefur eftir við léttan þrýsting.', 'Settu það í bréfpoka með epli til að flýta fyrir þroskanum.', false, true, '2026-11-16 14:05:34.747', '2026-11-16 14:05:34.747') ON CONFLICT DO NOTHING;
INSERT INTO "Fruit" ("id", "slug", "name", "variety", "illustration", "color", "imageUrl", "origin", "region", "farmer", "season", "description", "taste", "storage", "ripeness", "goodToKnow", "reviewed", "active", "createdAt", "updatedAt") VALUES ('cmwjc5xvv000s7dltqvi1yt6w', 'kiwi', 'Kiwi', '', 'kiwi', '#7CB342', '', 'Spánn', '', '', 'Vetur og vor', 'Kíví er ríkt af C-vítamíni.', 'Ferskt, sætt og örlítið súrt.', 'Geymist í kæli í nokkrar vikur.', 'Þroskað kíví gefur aðeins eftir við léttan þrýsting.', 'Kíví þroskast hraðar við stofuhita við hliðina á eplum eða banönum.', false, true, '2026-11-16 14:05:34.796', '2026-11-16 14:05:34.796') ON CONFLICT DO NOTHING;
INSERT INTO "Fruit" ("id", "slug", "name", "variety", "illustration", "color", "imageUrl", "origin", "region", "farmer", "season", "description", "taste", "storage", "ripeness", "goodToKnow", "reviewed", "active", "createdAt", "updatedAt") VALUES ('cmwjc5xx7000t7dltvcu7r6uv', 'epli', 'Epli', '', 'apple', '#D9342B', '', 'Spánn', '', '', 'Haust og vetur', 'Stökk og safarík epli.', 'Sæt og fersk.', 'Geymdu epli í kæli, þá haldast þau stökk lengur.', 'Tilbúin til neyslu.', 'Epli gefa frá sér etýlen sem flýtir fyrir þroska annarra ávaxta. Geymdu þau sér ef þú vilt hægja á þroskanum.', false, true, '2026-11-16 14:05:34.843', '2026-11-16 14:05:34.843') ON CONFLICT DO NOTHING;
INSERT INTO "Fruit" ("id", "slug", "name", "variety", "illustration", "color", "imageUrl", "origin", "region", "farmer", "season", "description", "taste", "storage", "ripeness", "goodToKnow", "reviewed", "active", "createdAt", "updatedAt") VALUES ('cmwjc5xyn000u7dltmgi0mjql', 'sitrona', 'Sítróna', '', 'lemon', '#F9C214', '', 'Spánn', '', '', 'Allt árið', 'Fersk sítróna, tákn Fincafresh.', 'Súr og fersk.', 'Geymist í kæli í 2–3 vikur.', 'Tilbúin til notkunar.', 'Rúllaðu sítrónunni á borðinu áður en þú kreistir hana, þá færðu meiri safa.', false, true, '2026-11-16 14:05:34.896', '2026-11-16 14:05:34.896') ON CONFLICT DO NOTHING;
INSERT INTO "Fruit" ("id", "slug", "name", "variety", "illustration", "color", "imageUrl", "origin", "region", "farmer", "season", "description", "taste", "storage", "ripeness", "goodToKnow", "reviewed", "active", "createdAt", "updatedAt") VALUES ('cmwjc5xzu000v7dltijb9hoqm', 'chirimoya', 'Chirimoya', '', 'cherimoya', '#9BBF5A', '', 'Spánn', '', '', 'Haust og vetur', 'Chirimoya er ræktuð á Costa Tropical á Suður-Spáni og hefur rjómakennt aldinkjöt.', 'Sætt og rjómakennt.', 'Við stofuhita þar til hún er þroskuð, svo í kæli í 1–2 daga.', 'Þroskuð þegar hún gefur eftir við léttan þrýsting og hýðið dökknar aðeins.', 'Fræin eru ekki æt. Skerðu ávöxtinn í tvennt og borðaðu aldinkjötið með skeið.', false, true, '2026-11-16 14:05:34.939', '2026-11-16 14:05:34.939') ON CONFLICT DO NOTHING;
INSERT INTO "Fruit" ("id", "slug", "name", "variety", "illustration", "color", "imageUrl", "origin", "region", "farmer", "season", "description", "taste", "storage", "ripeness", "goodToKnow", "reviewed", "active", "createdAt", "updatedAt") VALUES ('cmwjc5y12000w7dlt0yys6vsi', 'kaki', 'Kakí', '', 'persimmon', '#F27B1F', '', 'Spánn', '', '', 'Haust', 'Kakí (persimmon) er appelsínugulur haustávöxtur.', 'Sætt og hunangskennt.', 'Geymist í kæli í nokkra daga.', 'Fer eftir afbrigði; spurðu okkur ef þú ert í vafa.', '', false, true, '2026-11-16 14:05:34.983', '2026-11-16 14:05:34.983') ON CONFLICT DO NOTHING;
